/* HARDGATE — build stamp. Single source of truth for "which version am I running?"
   Loaded FIRST so every later script can read G.HG_BUILD. */
(function(){
'use strict';
var G = (typeof window !== 'undefined') ? window : globalThis;

var HG_BUILD = {
  version: 'hg-v932',
  pack: 'THE EXCURSIONS THAT WERE MEASURED AND THROWN AWAY, AND THE BARS THAT DECIDE OMNIGOLD SIGN. scripts/backtest-omnigold.mjs has computed tr.mfe and tr.mae on every filled bar since the 2R work, under a comment stating exactly why they exist - no artifact recorded that, mfe/mae are that record - AND settleRecord NEVER EMITTED THEM. The work was done and dropped on the way out, so the artifact still could not answer the question its own comment poses. backtest-goldscalp.mjs tracked none at all. The consequence: on gold every exit question - is the fixed target right, would a breakeven move pay, is the stop wider than it needs to be - has been not unresolved but UNMEASURABLE, while the crypto side has had hgHeatProfile and hgStopSweep since hg-v182 plus a full exit-optimisation artifact. That artifact is worth knowing about before anyone spends effort on gold exits: five families, TRAIL vs FIXED, several horizons, and NOTHING cleared the Sidak bar of 2.66 - best was SWEEP at z=2.10, GLOBAL at z=0.37. lib/gold-excursions.mjs now holds ONE rule both walks fold through and both EMIT as maeR and mfeR. The rule is conservative on purpose: a bar that touches the stop contributes NOTHING to the favourable excursion, because intrabar order is unknown and the walk already resolves a both-touch bar as a loss, so crediting the high of the bar that stopped the trade out would let the sweep invent gains no real fill ever saw. Shared rather than copied because two copies drift and the copy that drifts is the one that flatters its own desk. SECOND HALF: lib/ambiguous-bar.mjs and scripts/resolve-ambiguous.mjs go after the 672 both-touch rows - 8.3% of the OMNIGOLD filled book - that hg-v931 showed are the ENTIRE reason its win rate reads 30.4% at one fill bound and 38.6% at the other, below its 33.3% breakeven at one end and above it at the other. A finer bar inside the ambiguous one answers which came first. Bars are SORTED, NOT TRUSTED, because an out-of-order feed would otherwise silently pick the winner; and a finer bar that ITSELF holds both levels resolves NOTHING rather than guessing one level down, since a guess here writes itself straight into the desk win rate. It runs as its own pass over a committed artifact rather than inside the walk, for three reasons: re-runnable without a full re-bake, cannot destabilise the walk it post-processes, and testable with an injected fetch - which matters because the network route is frequently unavailable on the machines this is developed on. IT FAILS CONSERVATIVE EVERYWHERE: no finer bars, a window they do not cover, a still-ambiguous finer bar, a throwing fetch, a row with no exit stamp - each leaves the row exactly as the stop-first walk recorded it, flagged with the real reason, and the pass REFUSES to rewrite an artifact when nothing was resolved rather than adding flags and calling it progress. Run against the real book here: 672 found, 672 unresolved, HTTP 403 on every one, nothing written - the designed failure mode, not a crash. Honours HG_KLINES_BASE and HG_KLINES_PROXY per hg-v921, so a mirror or the repo own proxy both work. NO THRESHOLD MOVES and no outcome changes until a re-bake can fetch. Tests: tests/test-gold-excursions.mjs (30) and tests/test-ambiguous-bar.mjs (53); 18 of 18 mutations caught after first runs left three survivors, each a fixture of mine that could not distinguish the behaviour it claimed to test - an adverse-excursion order test whose deeper bar was also the last, a zero-risk check on a trade with no excursions to divide, and a direction guard whose fixture tripped the both-levels branch instead',
  built: '2026-09-22T00:00:00Z'
};

function hgBuildLabel(b){
  b = b || HG_BUILD;
  var v = String(b.version || '').replace(/^hg-/, '');
  var p = b.pack ? ' · ' + b.pack : '';
  return v ? v + p : 'unknown build';
}

function hgBuildParseVersion(text){
  try{
    if (typeof text !== 'string' || !text) return null;
    var m = text.match(/version\s*:\s*['"]([A-Za-z0-9._-]{1,64})['"]/);
    return m ? m[1] : null;
  }catch(e){ return null; }
}

function hgBuildCompare(loaded, live){
  if (!loaded || !live) return { state: 'unknown', reason: 'could not read one side' };
  if (String(loaded) === String(live)) return { state: 'fresh', reason: 'matches server' };
  return { state: 'stale', reason: 'server is on ' + live + ', this tab loaded ' + loaded };
}

function hgBuildDistance(loaded, live){
  try{
    var a = String(loaded || '').match(/(\d+)\s*$/);
    var b = String(live || '').match(/(\d+)\s*$/);
    if (!a || !b) return null;
    return (+b[1]) - (+a[1]);
  }catch(e){ return null; }
}

function hgBuildChipState(res, b){
  b = b || HG_BUILD;
  var label = hgBuildLabel(b);
  if (!res || res.state === 'pending') return { text: label, cls: 'ok', title: 'checking for newer build' };
  if (res.state === 'fresh') return { text: label, cls: 'ok', title: 'running current build (' + res.live + ')' };
  if (res.state === 'stale'){
    var d = hgBuildDistance(res.loaded, res.live);
    var behind = (d != null && d > 0) ? ' (' + d + ' behind)' : '';
    return { text: label + ' · STALE' + behind, cls: 'bad', title: res.reason + ' — hard-reload to pick it up' };
  }
  return { text: label + ' · ?', cls: 'warn', title: (res.reason || 'freshness unknown') + ' — offline or blocked' };
}

function hgBuildFreshness(fetchImpl){
  var f = (typeof fetchImpl === 'function') ? fetchImpl : (typeof G.fetch === 'function' ? G.fetch.bind(G) : null);
  var loaded = HG_BUILD.version;
  if (!f) return Promise.resolve({ state: 'unknown', loaded: loaded, live: null, reason: 'no fetch' });
  var url = './build-stamp.js?fresh=' + Date.now();
  return f(url, { cache: 'no-store' }).then(function(res){
    if (!res || !res.ok) throw new Error('http ' + (res && res.status));
    return res.text();
  }).then(function(text){
    var live = hgBuildParseVersion(text);
    var cmp = hgBuildCompare(loaded, live);
    return { state: cmp.state, loaded: loaded, live: live, reason: cmp.reason };
  }).catch(function(e){
    return { state: 'unknown', loaded: loaded, live: null, reason: (e && e.message) || 'network failed' };
  });
}

function hgBuildSwWaiting(){
  try{
    var sw = G.navigator && G.navigator.serviceWorker;
    if (!sw || !sw.controller) return Promise.resolve(false);
    return sw.getRegistration().then(function(reg){
      return !!(reg && reg.waiting);
    }).catch(function(){ return false; });
  }catch(e){ return Promise.resolve(false); }
}

function hgRenderBuildChip(el, res){
  try{
    var node = el || (G.document && G.document.getElementById('chipBuild'));
    if (!node) return null;
    var st = hgBuildChipState(res);
    node.textContent = '';
    var b = G.document.createElement('b');
    b.textContent = st.text;
    node.appendChild(b);
    node.title = st.title;
    node.className = 'statuschip hg-build-' + st.cls;
    return st;
  }catch(e){ return null; }
}

function hgRenderVerBadge(res){
  try{
    var node = G.document && G.document.getElementById('hgVerBadge');
    if (!node) return null;
    var v = String(HG_BUILD.version || '').replace(/^hg-/, '');
    if (!v){ node.style.display = 'none'; return null; }
    if (res && res.state === 'stale'){
      var d = hgBuildDistance(res.loaded, res.live);
      var behind = (d != null && d > 0) ? ' (' + d + ' behind)' : '';
      node.textContent = v + ' · STALE' + behind;
      node.className = 'verbadge verbadge-stale';
      node.title = (res.reason || 'stale') + ' — reloading…';
      return { stale: true };
    }
    node.textContent = v;
    node.className = 'verbadge';
    node.title = HG_BUILD.version + (HG_BUILD.pack ? (' · ' + HG_BUILD.pack) : '');
    return { stale: false };
  }catch(e){ return null; }
}

function hgBuildMaybeReload(res, storage, reloadFn){
  try{
    if (!res || res.state !== 'stale' || !res.live) return false;
    var store = storage;
    if (!store && G.sessionStorage) store = G.sessionStorage;
    if (!store || typeof store.getItem !== 'function') return false;
    var key = 'hg_build_reload_' + String(res.live);
    if (store.getItem(key)) return false;
    var reload = reloadFn;
    if (!reload && G.location && typeof G.location.reload === 'function') reload = G.location.reload.bind(G.location);
    if (typeof reload !== 'function') return false;
    store.setItem(key, '1');
    reload();
    return true;
  }catch(e){}
  return false;
}

function hgBuildApplyFreshness(res){
  try{
    if (!res) return res;
    hgRenderBuildChip(null, res);
    hgRenderVerBadge(res);
    G.HG_BUILD_FRESHNESS = res;
    hgBuildMaybeReload(res);
    return res;
  }catch(e){ return res; }
}

function hgBuildInit(){
  try{
    hgRenderBuildChip(null, null);
    hgRenderVerBadge(null);
    hgBuildFreshness().then(function(res){
      return hgBuildSwWaiting().then(function(waiting){
        if (waiting && res.state === 'fresh'){
          res = { state: 'stale', loaded: res.loaded, live: res.live, reason: 'new build downloaded' };
        }
        return hgBuildApplyFreshness(res);
      });
    });
    if (G.document && typeof G.document.addEventListener === 'function'){
      G.document.addEventListener('visibilitychange', function(){
        try{
          if (!G.document || G.document.visibilityState !== 'visible') return;
          hgBuildFreshness().then(hgBuildApplyFreshness);
        }catch(e){}
      });
    }
  }catch(e){}
}

G.HG_BUILD = HG_BUILD;
G.hgBuildLabel = hgBuildLabel;
G.hgBuildParseVersion = hgBuildParseVersion;
G.hgBuildCompare = hgBuildCompare;
G.hgBuildDistance = hgBuildDistance;
G.hgBuildChipState = hgBuildChipState;
G.hgBuildFreshness = hgBuildFreshness;
G.hgBuildSwWaiting = hgBuildSwWaiting;
G.hgRenderBuildChip = hgRenderBuildChip;
G.hgRenderVerBadge = hgRenderVerBadge;
G.hgBuildMaybeReload = hgBuildMaybeReload;
G.hgBuildApplyFreshness = hgBuildApplyFreshness;
G.hgBuildInit = hgBuildInit;

try{
  if (G.document){
    if (G.document.readyState === 'loading'){
      G.document.addEventListener('DOMContentLoaded', hgBuildInit);
    } else {
      hgBuildInit();
    }
  }
}catch(e){}

})();
